<?php
declare(strict_types=1);require_once dirname(__DIR__).'/bootstrap.php';
use Artdon\MaterialCenter\Services\DocumentService;
$pageTitle='文档与日志';$pageDescription='规格书、认证文件、图片资料和操作日志。';$activeMenu='documents';$service=new DocumentService();$tab=(string)($_GET['tab']??'documents');$documents=$service->rows(trim((string)($_GET['q']??'')));$logs=$tab==='logs'?$service->logs():[];$materials=(new Artdon\MaterialCenter\Services\MaterialMasterService())->rows();include MC_ROOT.'/components/layout_top.php';?>
<section class="mc-page"><div class="mc-page-header mc-page-header--compact"><div><h1>文档与日志</h1><p>受权限控制的文件版本、下载、修改日志和操作日志。</p></div><button class="mc-button mc-button--primary" data-open-modal="document-modal"><?=mc_icon('plus',16)?> 上传</button></div><div class="mc-tabs"><a class="<?=$tab==='documents'?'is-active':''?>" href="?tab=documents">规格书 / 认证 / 图片</a><a class="<?=$tab==='logs'?'is-active':''?>" href="?tab=logs">操作日志</a></div><?php if($tab==='logs'):?><div class="mc-panel"><table class="mc-simple-table"><thead><tr><th>时间</th><th>模块</th><th>对象</th><th>操作</th><th>操作者</th><th>结果</th></tr></thead><tbody><?php if(!$logs):?><tr><td colspan="6">暂无日志</td></tr><?php endif;foreach($logs as$log):?><tr><td><?=mc_h($log['created_at'])?></td><td><?=mc_h($log['module'])?></td><td><?=mc_h($log['object_type'].' #'.($log['object_id']??'—'))?></td><td><?=mc_h($log['action'])?></td><td><?=mc_h($log['actor_id']??'—')?></td><td><?=mc_h($log['result'])?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="mc-panel"><form class="mc-toolbar"><label class="mc-search"><?=mc_icon('search',17)?><input name="q" value="<?=mc_h($_GET['q']??'')?>" placeholder="搜索文件名或物料"></label></form><div class="mc-document-grid"><?php if(!$documents):?><div class="mc-empty-state"><strong>暂无文档</strong></div><?php endif;foreach($documents as$doc):?><article><span class="mc-document-icon"><?=mc_icon('file',24)?></span><div><strong><?=mc_h($doc['file_name'])?></strong><small><?=mc_h($doc['material_code'].' '.$doc['material_name'])?> · V<?=intval($doc['version_no']??1)?> · <?=number_format((int)($doc['file_size']??0)/1024,1)?>KB</small></div><a class="mc-button" href="<?=mc_h(mc_url('api/v1/documents.php?action=download&id='.(int)$doc['id']))?>">下载</a></article><?php endforeach;?></div></div><?php endif;?></section>
<div class="mc-modal" id="document-modal" data-modal><form class="mc-modal__panel" data-document-form enctype="multipart/form-data"><div class="mc-modal__header"><div><strong>上传物料文档</strong><span>最大 25MB，保留 SHA-256 和版本</span></div><button type="button" class="mc-icon-button" data-close-layer>×</button></div><div class="mc-modal__body"><input type="hidden" name="csrf_token" value="<?=mc_h(csrf_token())?>"><input type="hidden" name="action" value="upload"><div class="mc-form-grid"><label class="mc-field"><span>物料 *</span><select name="material_id" required><?php foreach($materials as$m):?><option value="<?=intval($m['id'])?>"><?=mc_h($m['material_code'].' '.$m['name'])?></option><?php endforeach;?></select></label><label class="mc-field"><span>类型</span><select name="document_type"><option value="datasheet">规格书</option><option value="certificate">认证</option><option value="image">图片</option><option value="drawing">图纸</option></select></label><label class="mc-field"><span>访问级别</span><select name="access_level"><option value="internal">内部</option><option value="engineering">工程</option><option value="purchasing">采购</option><option value="public">可公开</option></select></label><label class="mc-field"><span>文件 *</span><input type="file" name="file" required></label></div></div><div class="mc-modal__footer"><button type="button" class="mc-button" data-close-layer>取消</button><button class="mc-button mc-button--primary" type="submit">上传</button></div></form></div><script src="<?=mc_h(mc_url('assets/js/documents.js'))?>" defer></script><?php include MC_ROOT.'/components/layout_bottom.php';?>
